let naAuthProbePromise=null;
async function naConfirmSessionAfter401(path=''){
  if(path==='/auth/me'){showLogin();return false;}
  if(naAuthProbePromise)return await naAuthProbePromise;
  naAuthProbePromise=(async()=>{
    try{
      const r=await fetch('/api/auth/me',{method:'GET',credentials:'same-origin',cache:'no-store',headers:{'Accept':'application/json'}});
      if(r.ok){
        const u=await r.json();
        if(u&&u.username){state.user=u;if(u.csrf_token)state.csrf=u.csrf_token;return true;}
      }
      if(r.status===401){showLogin();return false;}
      return null;
    }catch{return null;}
    finally{naAuthProbePromise=null;}
  })();
  return await naAuthProbePromise;
}
function authMessage(msg=''){const raw=String(msg||'').trim(),key=raw.split(';')[0].trim();const map={INVALID_CREDENTIALS:'Tài khoản hoặc mật khẩu chưa đúng.',INVALID_MFA_CODE:'Mã MFA không đúng hoặc đã hết chu kỳ 30 giây. Hãy chờ mã mới rồi thử lại.',MFA_CHALLENGE_EXPIRED:'Phiên xác thực MFA đã hết hạn. Hãy đăng nhập lại bằng mật khẩu.',MFA_NOT_AVAILABLE:'MFA của tài khoản chưa sẵn sàng. Liên hệ quản trị viên Web.',MFA_SECRET_UNAVAILABLE:'Không đọc được khóa MFA. Liên hệ quản trị viên Web.',MFA_DISABLED:'MFA hiện đang tắt cho tài khoản này. Hãy đăng nhập lại.',LOGIN_REQUIRED:'Phiên đăng nhập đã hết hạn. Vui lòng đăng nhập lại.',LOGIN_RATE_LIMITED:'Đăng nhập sai quá nhiều lần. Hệ thống tạm khóa thử lại để bảo vệ tài khoản.',REGISTRATION_DISABLED:'Chức năng đăng ký tài khoản đang tắt.',USERNAME_TAKEN:'Tên đăng nhập này đã được sử dụng.',PASSWORD_CONFIRMATION_MISMATCH:'Mật khẩu xác nhận không khớp.',PASSWORD_TOO_SHORT:'Mật khẩu đăng ký phải có ít nhất 12 ký tự.',REGISTRATION_RATE_LIMITED:'Đăng ký quá nhiều lần từ địa chỉ này. Hãy thử lại sau.',REGISTRATION_CAP_REACHED:'Hệ thống đã đạt giới hạn tài khoản tự đăng ký.'};return map[key]||raw.replace('API timed out. Long operations should be submitted as jobs.','Backend phản hồi quá chậm. Hãy kiểm tra trạng thái Web và thử lại.').replace('API unreachable. Check the Web terminal.','Không kết nối được backend Web. Hãy bấm “Kiểm tra kết nối” và thử lại.')}
async function api(path,options={}){const method=(options.method||'GET').toUpperCase(),headers={'Content-Type':'application/json',...(options.headers||{})};if(method!=='GET'&&state.csrf)headers['X-CSRF-Token']=state.csrf;let r,lastErr;const attempts=method==='GET'?2:1;for(let attempt=0;attempt<attempts;attempt++){const ctrl=new AbortController(),timer=setTimeout(()=>ctrl.abort(),attempt?12000:20000);try{r=await fetch('/api'+path,{...options,headers,credentials:'same-origin',signal:ctrl.signal,cache:'no-store'});lastErr=null;break}catch(e){lastErr=e;if(attempt+1<attempts)await new Promise(res=>setTimeout(res,350))}finally{clearTimeout(timer)}}if(lastErr)throw new Error(lastErr.name==='AbortError'?'API timed out. Long operations should be submitted as jobs.':'API unreachable. Check the Web terminal.');let d;try{d=await r.json()}catch{throw new Error('Unexpected API response ('+r.status+')')}if(!r.ok){if(r.status===401&&path!=='/auth/login'&&path!=='/auth/mfa/verify')await naConfirmSessionAfter401(path);const msg=(typeof d.detail==='string'?d.detail:JSON.stringify(d.detail||d))+(Array.isArray(d.errors)?'\n'+d.errors.map(e=>(e.loc||[]).join('.')+': '+e.msg).join('\n'):'');throw new Error(authMessage(msg)+(d.request_id?' [ref '+d.request_id+']':''))}return d}
