function parseIds(text){const out=[];for(const part of String(text||'').split(',')){const t=part.trim();if(!t)continue;if(/^\d+-\d+$/.test(t)){let [a,b]=t.split('-').map(Number);if(a>b)[a,b]=[b,a];if(b-a>127)throw new Error('Khoảng Device ID quá lớn.');for(let i=a;i<=b;i++)if(i>0&&!out.includes(i))out.push(i)}else{const n=Number(t);if(!Number.isInteger(n)||n<=0)throw new Error('Device ID không hợp lệ: '+t);if(!out.includes(n))out.push(n)}}if(!out.length)throw new Error('Hãy nhập ít nhất một Managed Device ID.');if(out.length>128)throw new Error('Tối đa 128 thiết bị mỗi lần gán.');return out}
