function jobResultPreview(result){if(result===null||result===undefined)return '<p class="caption">Tác vụ chưa trả dữ liệu kết quả.</p>';const download=result&&typeof result==='object'&&!Array.isArray(result)&&result.download_url?`<p><a class="download-link" href="${esc(result.download_url)}" download>⬇ Tải ${esc(result.name||'kết quả')}</a></p>`:'';if(Array.isArray(result)&&result.length&&result.every(x=>x&&typeof x==='object'&&!Array.isArray(x))){const keys=[...new Set(result.slice(0,50).flatMap(x=>Object.keys(x)))].slice(0,8);const rows=result.slice(0,100);return download+table(rows,keys.map(k=>[k,k,(v)=>esc(typeof v==='object'?JSON.stringify(v):v??'—')]))+(result.length>100?`<p class="caption">Hiển thị 100/${result.length} dòng. Xem JSON để có toàn bộ dữ liệu.</p>`:'')+`<details><summary>JSON đầy đủ</summary><pre>${esc(JSON.stringify(result,null,2))}</pre></details>`}if(result&&typeof result==='object'&&!Array.isArray(result)){const scalar={},nested={};for(const [k,v] of Object.entries(result)){if(v===null||['string','number','boolean'].includes(typeof v))scalar[k]=v;else nested[k]=v}return download+(Object.keys(scalar).length?kv(scalar):'')+(Object.keys(nested).length?`<details open><summary>Chi tiết</summary><pre>${esc(JSON.stringify(nested,null,2))}</pre></details>`:'')}return `<pre>${esc(typeof result==='string'?result:JSON.stringify(result,null,2))}</pre>`}
function renderOperationResult(){const host=$('#operation-result');if(!host)return;const op=state.operation;if(!op||op.page!==state.page){host.innerHTML='';host.classList.add('hidden');return}const j=op.job||{},total=Number(j.total||0),done=Number(j.done||0),pct=total?Math.max(0,Math.min(100,Math.round(done/total*100))):null,finished=terminalJobStates.has(j.status);const tools=`<div class="operation-tools">${!finished&&j.id?button('Hủy tác vụ','job-cancel',{id:j.id},'danger'):''}${button('Đóng kết quả','operation-dismiss')}</div>`;const progress=total?`<div class="job-progress"><span style="width:${pct}%"></span></div><p class="caption">Tiến độ ${done}/${total} (${pct}%)</p>`:'';const body=`<div class="operation-summary">${metric('Task #',j.id||'—')}${metric('Chức năng',j.operation||op.label||'Task')}${metric('Trạng thái',j.status||'Queued',finished&&j.status==='Completed'?'green':finished?'amber':'')}${metric('Bắt đầu',j.created_at||'Đang xếp hàng')}</div>${progress}${j.error?`<div class="error">${esc(j.error)}</div>`:''}${finished?jobResultPreview(j.result):'<div class="operation-wait"><span class="spinner-inline"></span> Tác vụ đang chạy. Kết quả sẽ tự hiển thị tại đây, không chuyển trang.</div>'}`;host.innerHTML=panel(`Kết quả chức năng trên trang “${tr[op.page]||op.page}”`,body,tools);host.classList.remove('hidden')}
function watchJob(id,page,label=''){const token=++state.jobWatchToken;state.operation={page,label,job:{id,operation:label||'Task',status:'Queued',done:0,total:0}};renderOperationResult();const host=$('#operation-result');if(host&&!host.classList.contains('hidden'))host.scrollIntoView({behavior:'smooth',block:'nearest'});let checks=0;const poll=async()=>{if(token!==state.jobWatchToken||!state.user)return;try{const r=await api('/jobs/'+id);if(token!==state.jobWatchToken)return;state.operation={page,label,job:r};renderOperationResult();if(terminalJobStates.has(r.status)){toast(`Task #${id}: ${r.status}`,r.status!=='Completed');if(state.page===page)await go(page);return}}catch(e){if(token!==state.jobWatchToken)return;state.operation={page,label,job:{id,operation:label||'Task',status:'Failed',error:e.message,result:null}};renderOperationResult();return}checks++;if(checks>=900){state.operation.job.error='Dừng tự cập nhật sau 15 phút. Có thể xem tiếp trong Lịch sử tác vụ.';renderOperationResult();return}setTimeout(poll,1000)};setTimeout(poll,350)}
