const pages={};
pages.dashboard=async()=>{const [d,a,s,j]=await Promise.all([api('/dashboard'),api('/alerts?limit=8'),api('/server-targets'),canWrite()?api('/jobs'):Promise.resolve([])]);const total=Math.max(1,Number(d.devices||0)),pct=Math.max(0,Math.min(100,Math.round(Number(d.online||0)/total*100))),circ=251.2,arc=(circ*pct/100).toFixed(1)+' '+circ.toFixed(1);const offline=a.filter(x=>String(x.status||'').toLowerCase()!=='closed').slice(0,4);const running=j.filter(x=>['Queued','Running'].includes(x.status)).length;return `<div class="noc-hero"><div class="hero-copy"><div class="kicker">ONE-CLICK NOC / REAL OPERATIONS</div><h2>Trung tâm vận hành mạng</h2><p>Quan sát theo thời gian, tác vụ có kiểm soát và dữ liệu lấy trực tiếp từ NetworkAutomation. Hiệu ứng giao diện không thay thế số liệu đo thật.</p></div><div class="hero-actions">${canWrite()?button('One-click LAN check','job',{op:'LAN_PROBE'},'primary'):''}${button('LAN Readiness','page',{page:'lan'})}${button('Topology','page',{page:'topology'})}${isAdmin()?button('Production Health','page',{page:'production'}):''}</div></div>`+`<div class="noc-grid"><div class="noc-tile"><h4>Thiết bị / Fresh state</h4><div class="ring-wrap"><svg class="ring" viewBox="0 0 100 100" aria-label="${pct}% online"><circle class="track" cx="50" cy="50" r="40"/><circle class="inner" cx="50" cy="50" r="31"/><circle class="value" cx="50" cy="50" r="40" stroke-dasharray="${arc}"/></svg><div><div class="noc-number">${esc(d.devices)}</div><div class="noc-sub">${pct}% Online theo dữ liệu mới</div></div></div><div class="status-strip"><span class="status-pill good">Online ${esc(d.online)}</span><span class="status-pill bad">Offline ${esc(d.offline)}</span><span class="status-pill warn">Unknown ${esc(d.unknown)}</span><span class="status-pill warn">Path ${esc(d.path_issue||0)}</span><span class="status-pill">No reply ${esc(d.no_reply||0)}</span></div></div><div class="noc-tile"><h4>Telemetry</h4><div class="noc-number">${esc(d.health_samples)}</div><div class="noc-sub">Health samples đã lưu</div><div class="pulse-chart"></div><div class="status-strip"><span class="status-pill">Stale ${esc(d.stale)}</span><span class="status-pill">IP/MAC ${esc(d.ip_mac)}</span></div></div><div class="noc-tile"><h4>Cảnh báo mở</h4><div class="noc-number">${esc(d.alerts)}</div><div class="noc-sub">Không đóng / chưa resolved</div><div class="device-stack">${offline.length?offline.map(x=>`<span><b>${esc(x.ip||'—')}</b><i>${esc(x.severity||x.status||'Open')}</i></span>`).join(''):'<span>Không có cảnh báo mở gần đây</span>'}</div></div><div class="noc-tile"><h4>Tác vụ vận hành</h4><div class="noc-number">${running}</div><div class="noc-sub">Queued / Running</div><div class="pulse-chart"></div><div class="status-strip"><span class="status-pill good">Live ${state.live?'ON':'OFF'}</span><span class="status-pill">Auto IP ${esc(d.autoip_targets)}</span></div></div></div>`+`<div class="grid2">${panel('Application / Server',table(s,[['Tên','name'],['Host','host'],['Trạng thái','status',badge],['Dữ liệu','data_state',badge],['Kiểm tra','checked_at']]))}${panel('Sự cố & cảnh báo gần đây',table(a,[['Mức','severity',badge],['IP','ip'],['Nội dung','message'],['Trạng thái','status',badge]]))}</div>`+panel('Độ tin cậy dữ liệu',`<p class="caption">Online lịch sử không được dùng như trạng thái hiện tại. Unknown/STALE không đồng nghĩa Offline. CPU, RAM, RTT chỉ hiển thị khi có phép đo thực tế.</p>`)};

const deviceCols=[['IP','ip'],['Hostname','hostname'],['MAC','mac'],['Status','status',badge],['Data','data_state',badge],['Observed','observed_at'],['Source','observation_source'],['Managed ID','managed_id']];
function deviceRows(rows){return table(rows,deviceCols,r=>button('Details','device-detail',{id:r.id})+(canWrite()?button('Ping','job',{op:'PING',id:r.id}):'')+(isAdmin()?button('Edit','device-edit',{id:r.id})+(!r.managed_id?button('Enable managed tasks','device-manage',{id:r.id}):'')+button('Delete','device-delete',{id:r.id},'danger'):''))}

pages.devices=async()=>{state.cache=await api('/devices');return panel('Device inventory',`<div class="toolbar"><input id="device-filter" placeholder="Filter IP / hostname / MAC" aria-label="Filter devices"><span class="right muted">${state.cache.length} records</span>${isAdmin()?button('Add device','device-add',{},'primary'):''}</div><div id="device-table">${deviceRows(state.cache.filter(r=>{const q=($('#device-filter')?.value||'').toLowerCase();return !q||[r.ip,r.hostname,r.mac].some(v=>String(v||'').toLowerCase().includes(q));}))}</div>`)};
pages.server=async()=>{state.cache=await api('/server-targets');return panel('Server / Application targets',`<div class="toolbar">${isAdmin()?button('Add target','server-add',{},'primary'):''}${canWrite()?button('Run checks','job',{op:'SERVER_CHECK'}):''}</div>`+table(state.cache,[['Name','name'],['Host','host'],['Protocol','protocol'],['Port','port'],['Status','status',badge],['Validation','validation_error',v=>v?badge('Invalid'):'—'],['Data','data_state',badge],['Latency ms','latency_ms'],['CPU %','cpu'],['RAM %','ram'],['Checked','checked_at']],r=>button('History','server-history',{id:r.id})+(isAdmin()?button('Edit','server-edit',{id:r.id})+button('Delete','server-delete',{id:r.id},'danger'):'')))};
pages.health=async()=>{const h=await api('/health/latest?limit=1000');return panel('Latest observation per host',table(h,[['Host','host'],['CPU %','cpu'],['RAM %','memory'],['Latency ms','latency_ms'],['Loss %','packet_loss'],['Collected','created_at'],['Freshness','data_state',badge]]))};
pages.alerts=async()=>panel('Alerts',table(await api('/alerts?limit=1000'),[['Severity','severity',badge],['IP','ip'],['Message','message'],['Status','status',badge],['Created','created_at']],r=>canWrite()?button(String(r.status).toLowerCase()==='closed'?'Reopen':'Close','alert-state',{id:r.id,mode:String(r.status).toLowerCase()==='closed'?'reopen':'close'}):''));
pages.incidents=async()=>{const [i,r]=await Promise.all([api('/incidents?limit=1000'),api('/root-causes?limit=1000')]);return panel('Trung tâm sự cố',`<div class="toolbar">${canWrite()?button('Đồng bộ cảnh báo → Incident','job',{op:'INCIDENT_SYNC'},'primary')+button('Phân tích RCA','job',{op:'RCA_ANALYZE'}):''}</div>`+table(i,[['ID','id'],['Mức','severity',badge],['Host','host'],['Sự cố','title'],['Trạng thái','status',badge],['Số cảnh báo','alert_count'],['Lần cuối','last_seen']],x=>canWrite()?button('Open','incident-state',{id:x.id,status:'Open'})+button('Acknowledged','incident-state',{id:x.id,status:'Acknowledged'})+button('Resolved','incident-state',{id:x.id,status:'Resolved'}):''))+panel('Phân tích nguyên nhân gốc (bằng chứng lịch sử)',table(r,[['Root host','root_host'],['Tiêu đề','title'],['Mức','severity',badge],['Trạng thái','status',badge],['Ảnh hưởng','impacted_count'],['Dữ liệu','data_state',badge],['Lần cuối','last_seen']]));};
function topologySvg(data){const nodes=(data.nodes||[]).slice(0,80),links=data.links||[];if(!nodes.length)return empty('Chưa có managed device.');const W=1000,H=520,cx=W/2,cy=H/2,R=Math.min(W,H)*.38,pos={};nodes.forEach((n,i)=>{const a=(Math.PI*2*i/nodes.length)-Math.PI/2;pos[n.id]={x:cx+R*Math.cos(a),y:cy+R*Math.sin(a)}});const lines=links.filter(l=>pos[l.source_id]&&pos[l.target_id]).map(l=>`<line x1="${pos[l.source_id].x}" y1="${pos[l.source_id].y}" x2="${pos[l.target_id].x}" y2="${pos[l.target_id].y}" class="topo-link"><title>${esc(l.label||l.source||'link')}</title></line>`).join('');const ns=nodes.map(n=>{const p=pos[n.id],cls=String(n.status||'unknown').toLowerCase();return `<g class="topo-node ${cls}"><circle cx="${p.x}" cy="${p.y}" r="16"></circle><text x="${p.x}" y="${p.y+32}" text-anchor="middle">${esc((n.name||n.ip||'').slice(0,18))}</text><title>${esc(n.ip||'')} / ${esc(n.status||'Unknown')}</title></g>`}).join('');return `<div class="topology-wrap"><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Network topology">${lines}${ns}</svg></div>`}
pages.topology=async()=>{const d=await api('/v4/topology');state.topology=d;state.managed=d.nodes||[];return panel('Sơ đồ mạng',topologySvg(d),canWrite()?button('Phát hiện LLDP/CDP','job',{op:'TOPOLOGY_DISCOVER'},'primary'):'')+panel('Liên kết quản lý',table(d.links,[['ID','id'],['Source ID','source_id'],['Target ID','target_id'],['Label','label'],['Nguồn','source'],['Time','created_at']],r=>isAdmin()&&r.source==='Dependency'?button('Xóa dependency','dep-delete',{id:r.id},'danger'):''),isAdmin()?button('Thêm dependency','dep-add'): '')+panel('LLDP/CDP observations',table(d.discovery,[['Protocol','protocol'],['Local','local_host'],['Local port','local_port'],['Remote','remote_name'],['Remote port','remote_port'],['Time','discovered_at']]));};
pages.sla=async()=>{const [p,a,m]=await Promise.all([api('/v4/sla'),api('/v4/availability?days=30'),api('/v4/maintenance')]);state.sla=p;state.maintenance=m;const avail=a.filter(x=>x.availability!==null);return `<div class="cards">${metric('SLA policies',p.length)}${metric('Thiết bị có mẫu',avail.length)}${metric('Đạt ≥99%',avail.filter(x=>x.availability>=99).length,'green')}${metric('Maintenance',m.filter(x=>x.enabled).length)}</div>`+panel('SLA policies',table(p,[['ID','id'],['Tên','name'],['Scope','scope_type'],['Target %','target_percent'],['Period','period_days'],['Availability %','availability'],['Samples','sample_count'],['Đạt','met',v=>v===null?badge('Unknown'):badge(v?'Pass':'Fail')]],r=>isAdmin()?button('Sửa','sla-edit',{id:r.id})+button('Xóa','sla-delete',{id:r.id},'danger'):''),isAdmin()?button('Thêm SLA','sla-add',{},'primary'):'')+panel('Availability 30 ngày',table(a,[['Device','name'],['IP','ip'],['Availability %','availability'],['Samples','samples'],['Excluded','excluded']],r=>button('Capacity 7d','capacity-view',{id:r.id})))+panel('Maintenance windows',table(m,[['ID','id'],['Tên','name'],['Scope','scope_type'],['Host','host'],['Start','start_at'],['End','end_at'],['Suppress alerts','suppress_alerts',v=>badge(v?'Yes':'No')],['Enabled','enabled',v=>badge(v?'Yes':'No')]],r=>isAdmin()?button('Sửa','maintenance-edit',{id:r.id})+button('Xóa','maintenance-delete',{id:r.id},'danger'):''),isAdmin()?button('Thêm maintenance','maintenance-add'): '');};
pages.scheduler=async()=>{const x=await api('/v4/schedules');state.schedules=x;return panel('Lịch vận hành',`<p class="caption">Scheduler chỉ gọi operation whitelist; không hỗ trợ shell tùy ý và không tự lập lịch Restore Config.</p>`+table(x,[['ID','id'],['Tên','name'],['Operation','operation'],['Interval min','interval_minutes'],['Enabled','enabled',v=>badge(v?'Yes':'No')],['Last','last_run'],['Last status','last_status',badge],['Job','last_job_id']],r=>(r.can_run?button('Run now','schedule-run',{id:r.id}):'<span class="caption">Không có quyền chạy</span>')+(isAdmin()?button('Sửa','schedule-edit',{id:r.id})+button('Xóa','schedule-delete',{id:r.id},'danger'):'')),isAdmin()?button('Thêm lịch','schedule-add',{},'primary'):'');};
pages.restore=async()=>{const [r,d]=await Promise.all([api('/v4/restore'),api('/managed-devices')]);state.restore=r;state.managed=d;return panel('Khôi phục cấu hình có kiểm soát',`<p class="caption">Chỉ backup do Web quản lý mới được restore. Web thực thi restore Cisco-like sau preview, cụm xác nhận và safety backup.</p>`+table(r.backups,[['ID','id'],['Device','device_name'],['Source','source'],['File','filename'],['Bytes','size_bytes'],['Restorable','restorable',v=>badge(v?'Ready':'Blocked')],['Created','created_at']],x=>x.restorable?button('Preview / Prepare','restore-prepare',{id:x.id},'danger'):''))+panel('Restore history',table(r.history,[['User','username'],['Device','device_name'],['IP','ip'],['Backup','backup_id'],['Status','status',badge],['Detail','detail'],['Time','created_at']]));};
pages.extensions=async()=>{const e=await api('/v4/extensions');state.cameras=e.cameras;const w=e.wifi_status||{};return `<div class="cards">${metric('Camera',e.cameras.length)}${metric('Wi-Fi',w.status||(e.wifi_supported?'PASS':'N/A'))}${metric('History',e.history.length)}</div>`+panel('Wi-Fi diagnostics',`<p class="caption">${esc(w.detail||'Đọc netsh WLAN trên máy Windows chạy Web; không thay đổi cấu hình Wi-Fi.')}</p>${w.status==='N/A'?'<div class="empty"><b>N/A</b>Máy chạy Web không có Wi-Fi adapter; đây không phải lỗi hệ thống.</div>':(canWrite()?button('Chạy Wi-Fi diagnostics','wifi-run',{},'primary'):'')}`)+panel('Camera / NVR endpoints',table(e.cameras,[['ID','id'],['Tên','name'],['Host','host'],['Port','port'],['Stream saved','has_stream',v=>badge(v?'Encrypted':'No')],['Snapshot saved','has_snapshot',v=>badge(v?'Encrypted':'No')]],r=>canWrite()?button('Check TCP','camera-check',{id:r.id})+(isAdmin()?button('Sửa','camera-edit',{id:r.id})+button('Xóa','camera-delete',{id:r.id},'danger'):''):''),isAdmin()?button('Thêm camera','camera-add'): '')+panel('Extension history',table(e.history,[['Kind','kind'],['Target','target'],['Status','status',badge],['Detail','detail'],['Time','created_at']]));};
pages.organization=async()=>{const o=await api('/v4/organization');state.org=o;return panel('Sites',table(o.sites,[['ID','id'],['Tên','name'],['Location','location'],['Note','note']],r=>isAdmin()?button('Sửa','site-edit',{id:r.id})+button('Xóa','site-delete',{id:r.id},'danger'):''),isAdmin()?button('Thêm Site','site-add',{},'primary'):'')+panel('Nhóm thiết bị',table(o.groups,[['ID','id'],['Tên','name'],['Note','note']],r=>isAdmin()?button('Sửa','group-edit',{id:r.id})+button('Xóa','group-delete',{id:r.id},'danger'):''),isAdmin()?button('Thêm nhóm','group-add'): '')+panel('Gán thiết bị',table(o.devices,[['ID','id'],['Device','name'],['IP','ip'],['Vendor','vendor'],['Site','site'],['Group','device_group'],['VLAN','vlan'],['Tags','tags']],r=>isAdmin()?button('Gán / sửa','org-assign',{id:r.id}):''));};
pages.security=async()=>{const [a,c,e]=await Promise.all([api('/security/assets?limit=2000'),api('/security/checks?limit=500'),api('/security/events?limit=500')]);return `<div class="cards">${metric('Security assets',a.length)}${metric('Security checks',c.length)}${metric('Security events',e.length)}</div>`+panel('Danh tính tài sản',table(a,[['IP','ip'],['Hostname kỳ vọng','expected_hostname'],['MAC kỳ vọng','expected_mac'],['Mức quan trọng','criticality',badge],['Identity','identity_status',badge],['Xác minh cuối','last_verified']]))+panel('Security checks',table(c,[['IP','asset_ip'],['Kiểm tra','check_type'],['Kết quả','result',badge],['Mức','severity',badge],['Thời gian','created_at']]))+panel('Security events',table(e,[['IP','asset_ip'],['Nguồn','source'],['Loại','event_type'],['Mức','severity',badge],['Tiêu đề','title'],['Trạng thái','status',badge],['Thời gian','updated_at']]));};
pages.logs=async()=>{const s=await api('/system-logs?limit=300');let html=panel('Hoạt động hệ thống',table(s.activity,[['Hành động','action'],['Mô tả','description'],['Thời gian','created_at']]))+panel('Thông báo',table(s.notifications,[['Kênh','channel'],['Trạng thái','status',badge],['Chi tiết','detail'],['Thời gian','created_at']]))+panel('Sức khỏe thành phần',table(s.health,[['Thành phần','component'],['Trạng thái','status',badge],['Chi tiết','detail'],['Thời gian','created_at']]));if(isAdmin()){const a=await api('/audit-log?limit=300');html+=panel('Audit quản trị',table(a,[['Tài khoản','username'],['Vai trò','role'],['Hành động','action'],['Đích','target'],['Chi tiết','detail'],['Thời gian','created_at']]));}return html;};
pages.ipmac=async()=>panel('IP / MAC inventory',table(await api('/ip-mac?limit=3000'),[['IP','ip'],['MAC','mac'],['Hostname','hostname'],['Status (stored)','status',badge],['First seen','first_seen'],['Last seen','last_seen']]));
pages.scan=async()=>{const ident=await api('/v50/network/identity');if(String(ident.source||'').toUpperCase()==='BROWSER'){return panel('Khám phá mạng trên bản Web',`<div class="cards">${metric('Chế độ','BROWSER ONLY','green')}${metric('IP Internet',ident.ipv4||'—')}${metric('LAN private','Không được trình duyệt cấp quyền')}</div><div class="notice"><b>Đã khóa quét LAN trên Render.</b> Nút quét cũ từng chạy từ host nên có thể trả về mạng của Render thay vì mạng của máy đang mở Web. Hotfix16P không cho phép hành vi đó nữa.</div><p class="caption">Chrome/Edge/Safari không cung cấp API chung để website đọc ARP/MAC, gateway hoặc quét toàn bộ 192.168.x.x của thiết bị truy cập. Vì vậy bản Web-only chỉ hiển thị IP Internet công khai và các phép đo HTTPS của chính trình duyệt.</p>`)+panel('Muốn quét LAN thật của máy đang mở Web',`<div class="empty"><b>Cần một điểm thực thi nằm trong LAN</b>Không thể đạt quét LAN thật chỉ bằng website trên Render. Các lựa chọn kỹ thuật là Local Agent, browser extension/native helper, API của router/controller, hoặc một collector/NAS/Raspberry Pi trong LAN. Nếu giữ yêu cầu “không cài/chạy gì trên máy”, chức năng quét LAN phải để ở trạng thái không khả dụng thay vì quét nhầm host.</div>`);}const results=await api('/scan-results');return panel('Network discovery',isAdmin()?form('scan-form',input('Authorized private IPv4 CIDR','network','text','','true'),'Queue scan')+'<p class="caption">Maximum 1024 private IPv4 addresses. Scan results are observations only; they are NOT added to inventory automatically. Import an Online host explicitly after review.</p>':'Read-only')+panel('Recorded scan runs',table(await api('/scan-history'),[['Network','network'],['Total','total_hosts'],['Online','online_hosts'],['State','status',badge],['Started','start_time']]))+panel('Discovered hosts',table(results,[['Network','network'],['IP','ip'],['Hostname','hostname'],['MAC','mac'],['Status','status',badge],['Latency','latency_ms'],['Inventory','inventory_id',v=>v?badge('Added'):badge('Not added')],['Time','created_at']],r=>isAdmin()&&String(r.status).toLowerCase()==='online'&&!r.inventory_id?button('Add to inventory','scan-import',{id:r.id},'primary'):''));};
pages.autoip=async()=>{const [t,h,s]=await Promise.all([api('/autoip/targets'),api('/autoip/history'),api('/autoip/status')]);return panel('Auto Ping / Auto IP coordinator',`<div class="toolbar">${badge(s.status)}<span>${s.done||0} / ${s.total||0}</span>${isAdmin()?(s.enabled?button('Chạy kiểm tra','auto-start',{},'primary'):'<button disabled>Auto Ping / Auto IP đang tắt</button>')+(s.running?button('Dừng','auto-stop',{},'danger'):''):''}</div><p class="caption">Bản Web hosted tự khởi động cùng dịch vụ máy chủ. Auto Ping / Auto IP chỉ hoạt động khi backend có quyền truy cập mạng đích; trình duyệt người dùng không cần chạy Agent hay công cụ cục bộ.</p>`)+panel('Danh sách IP thực tế',table(t,[['IP','ip'],['Tên','name'],['Profile','profile']]))+panel('Lịch sử chạy',table(h,[['Run ID','run_id'],['Trạng thái','status',badge],['Bắt đầu','started_at'],['Kết thúc','finished_at']],r=>button('Chi tiết','auto-steps',{id:r.run_id}))) };
pages.snmp=async()=>{const [d,h]=await Promise.all([api('/managed-devices'),api('/snmp/diagnostics')]);return panel('Managed devices / SNMP',table(d,[['Managed ID','id'],['Name','name'],['IP','ip'],['Vendor','vendor']],r=>canWrite()?button('Refresh','job',{op:'SNMP',id:r.id}):''))+panel('Diagnostics history',table(h,[['Host','host'],['Version','version'],['Success','success',v=>badge(v?'Completed':'Failed')],['sysName','sys_name'],['Detail','detail'],['Time','created_at']]))};
pages.audit=async()=>{const [d,h]=await Promise.all([api('/ssh-audit/devices'),api('/ssh-audit/history')]);return panel('SSH configuration audit',table(d,[['Managed ID','id'],['IP','ip'],['Name','name'],['Assigned credential','credential_name']],r=>isAdmin()?button('Read-only audit','job',{op:'AUDIT',id:r.id}):''))+panel('Audit history',table(h,[['Device','device_name'],['IP','ip'],['State','status',badge],['Detail','detail'],['Time','created_at']]))};
