notify:async()=>{const r=await api('/v44/notifications');state.v44notify=r;const s=r.settings||{};const ck=(n,v,l)=>`<label class="check"><input type="checkbox" name="${n}" ${String(v)==='1'||v===true?'checked':''}> ${esc(l)}</label>`;const fields=ck('notify_enabled',s.notify_enabled,'Bật notification')+ck('notify_telegram',s.notify_telegram,'Telegram')+ck('notify_email',s.notify_email,'Email')+ck('notify_offline',s.notify_offline,'Offline')+ck('notify_drift',s.notify_drift,'Config drift')+ck('notify_security',s.notify_security,'Security')+ck('notify_daily_audit',s.notify_daily_audit,'Daily audit')+input('Cooldown phút','notify_cooldown_min','number',s.notify_cooldown_min||60)+input('Telegram chat ID','telegram_chat_id','text',s.telegram_chat_id||'',false)+input(`Telegram token mới${s.has_telegram_token?' (đã có, trống = giữ)':''}`,'telegram_token','password','',false)+input('SMTP host','smtp_host','text',s.smtp_host||'',false)+input('SMTP port','smtp_port','number',s.smtp_port||587)+input('SMTP user','smtp_user','text',s.smtp_user||'',false)+input(`SMTP password mới${s.has_smtp_password?' (đã có, trống = giữ)':''}`,'smtp_password','password','',false)+input('SMTP to','smtp_to','text',s.smtp_to||'',false);return (isAdmin()?panel('Notification settings',form('notification-form',fields,'Lưu cấu hình')+`<div class="toolbar">${button('Test Telegram','notify-test',{channel:'Telegram'})}${button('Test Email','notify-test',{channel:'Email'})}</div>`):'')+panel('Notification log',table(r.logs,[['Time','created_at'],['Event','event_key'],['Channel','channel'],['Status','status',badge],['Detail','detail']]));},
