function driverFields(x={}){return input('Name','name','text',x.name||'')+input('Vendor','vendor','text',x.vendor||'',false)+input('Priority','priority','number',x.priority??50)+input('sysObject prefix','sysobject_prefix','text',x.sysobject_prefix||'',false)+input('Description regex','descr_regex','text',x.descr_regex||'',false)+input('CPU OID','cpu_oid','text',x.cpu_oid||'',false)+input('Memory used OID','mem_used_oid','text',x.mem_used_oid||'',false)+input('Memory total OID','mem_total_oid','text',x.mem_total_oid||'',false)+select('LLDP mode','lldp_mode',['LLDP','LLDP/CDP','CDP','None'],x.lldp_mode||'LLDP')+select('Backup command','backup_command',[['','None'],['show running-config','show running-config'],['display current-configuration','display current-configuration'],['show configuration','show configuration'],['/export terse','/export terse']],x.backup_command||'')+input('Save command (metadata only)','save_command','text',x.save_command||'',false)+input('Note','note','text',x.note||'',false)+select('Enabled','enabled',[[1,'Yes'],[0,'No']],x.enabled===0?0:1)}
